 async function addFriendByUsername(name:string){if(!supabase)return;const {error}=await supabase.rpc('send_friend_request',{p_username:name});if(error)notify(prettyError(error));else{notify('تصيفط طلب الصداقة لـ '+name);void loadFriends();setPublicProfileId(null);}}
 const loadProfile=useCallback(async()=>{if(!supabase||!userId)return;const {profile:loadedProfile,error}=await fetchProfile(supabase,userId);if(error||!loadedProfile){notify('ما قدرناش نحملو البروفايل: '+prettyError(error));return;}setProfile(loadedProfile);setProfileName(loadedProfile.username);setBio(loadedProfile.bio||'');},[userId]);
