 async function sendRoomInvite(friend:any){if(!supabase||!userId||!room)return;const {error}=await supabase.rpc('send_room_invite',{p_room_id:room.id,p_friend_id:friend.profile.id});if(error)notify(prettyError(error));else notify('تصيفطات الدعوة لـ '+friend.profile.username);}
 async function markNotificationRead(id:string){if(!supabase)return;await supabase.from('notifications').update({read_at:new Date().toISOString()}).eq('id',id);setNotifications(prev=>prev.map(n=>n.id===id?{...n,read_at:new Date().toISOString()}:n));} async function respondRoomInvite(n:AppNotification,accept:boolean){if(!supabase)return;const {data,error}=await supabase.rpc('respond_room_invite',{p_notification_id:n.id,p_accept:accept});if(error){notify(prettyError(error));return;}const status=data?.status as string|undefined;if(status==='accepted'){setNotificationOpen(false);setNotifications(prev=>prev.map(item=>item.id===n.id?{...item,read_at:new Date().toISOString(),payload:{...item.payload,status:'accepted'}}:item));await openRoom({id:data.room_id,code:data.room_code,name:data.room_name,is_private:false,max_players:data.max_players||16,status:'open',game_key:data.game_key});return;}if(status==='full'){setDismissedInviteIds(previous=>previous.includes(n.id)?previous:[...previous,n.id]);notify('الغرفة عامرة دابا. جرب من بعد إلا خرج شي لاعب.');return;}setNotifications(prev=>prev.map(item=>item.id===n.id?{...item,read_at:new Date().toISOString(),payload:{...item.payload,status:status|| (accept?'unavailable':'declined')}}:item));notify(status==='declined'?'ترفضات الدعوة.':status==='expired'?'سالَت صلاحية الدعوة.':status==='unavailable'?'الغرفة ما بقاتش متاحة.':'ما قدرناش نقبلو الدعوة.');}
 async function quickMatch(){if(!supabase||!userId||busy)return;if(room){setTab(game?.game_key==='haunted_camp'?'game':'room');return;}setBusy(true);const {data,error}=await supabase.rpc('quick_match_room',{p_game_key:'haunted_camp'});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(!r){notify('ما لقيناش مخيم مناسب. حاول مرة أخرى.');return;}await openRoom({id:r.room_id,code:r.room_code,name:r.room_name,is_private:false,max_players:Number(r.max_players)||10,status:'open',game_key:'haunted_camp'});const {data:membership}=await supabase.from('room_members').select('role').eq('room_id',r.room_id).eq('user_id',userId).maybeSingle();if(membership?.role==='owner'){setBusy(true);const {data:gameId,error:startError}=await supabase.rpc('start_haunted_game',{p_room_id:r.room_id,p_quick_mode:false});setBusy(false);if(startError){notify(prettyError(startError));return;}setGame({id:gameId as string,game_key:'haunted_camp',status:'active',created_by:userId});setTab('game');}}
