 async function uploadAvatar(file?:File){if(!file||!supabase||!userId)return;if(!file.type.startsWith('image/')||file.size>5*1024*1024){notify('اختار صورة أقل من 5MB.');return;}setAvatarBusy(true);try{const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=userId+'/'+Date.now()+'.'+ext;const {error:upErr}=await supabase.storage.from('avatars').upload(path,file,{upsert:true,contentType:file.type,cacheControl:'3600'});if(upErr)throw upErr;const {data}=supabase.storage.from('avatars').getPublicUrl(path);const {error}=await supabase.rpc('update_my_profile',{p_username:profileName||profile?.username||session.user.email?.split('@')[0]||'Player',p_bio:bio||'',p_avatar_url:data.publicUrl});if(error)throw error;await loadProfile();notify('تبدلات صورة البروفايل بنجاح.');}catch(e:any){notify(prettyError(e));}finally{setAvatarBusy(false);}}
 useEffect(()=>{if(!supabase)return;supabase.auth.getSession().then(({data})=>setSession(data.session));const {data:{subscription}}=supabase.auth.onAuthStateChange((event,next)=>{setSession(next);if(event==='PASSWORD_RECOVERY')setPasswordRecovery(true);});return()=>subscription.unsubscribe();},[]);
 useEffect(()=>{if(!userId){setProfile(null);setRoom(null);return;}void loadProfile();void loadRooms();void loadLeaderboard();void loadDailyMissions();void loadFriends();void restoreActiveHauntedRoom();},[userId,loadProfile,loadRooms,loadLeaderboard,loadDailyMissions]);
 useEffect(()=>{const client=supabase;if(!client||!userId)return;void loadNotifications();const channel=client.channel('mimox-presence',{config:{presence:{key:userId}}});channel.on('presence',{event:'sync'},()=>{const state=channel.presenceState();setOnlineIds(Object.keys(state));}).subscribe(async status=>{if(status==='SUBSCRIBED')await channel.track({user_id:userId,online_at:new Date().toISOString()});});const feed=client.channel('mimox-notifications:'+userId).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'user_id=eq.'+userId},payload=>{const n=payload.new as AppNotification;setNotifications(old=>[n,...old].slice(0,30));playGameSound('notification');notify(n.title+': '+n.body);}).subscribe();return()=>{void client.removeChannel(channel);void client.removeChannel(feed);};},[userId,loadNotifications]);
 useEffect(()=>{const client=supabase;if(!client||!userId||!selectedFriend)return;const friendId=selectedFriend.profile.id;setDirectTyping(false);void loadDirectMessages(friendId);const channel=client.channel('dm:'+([userId,friendId].sort().join(':')),{config:{private:true}}).on('postgres_changes',{event:'INSERT',schema:'public',table:'direct_messages'},payload=>{const m=payload.new as DirectMessage;if((m.sender_id===userId&&m.recipient_id===friendId)||(m.sender_id===friendId&&m.recipient_id===userId)){setDirectMessages(old=>old.some(x=>x.id===m.id)?old:[...old,m]);if(m.sender_id===friendId){playGameSound('message');void client.from('direct_messages').update({read_at:new Date().toISOString()}).eq('id',m.id);}}}).on('postgres_changes',{event:'UPDATE',schema:'public',table:'direct_messages'},payload=>{const m=payload.new as DirectMessage;if(m.sender_id===userId&&m.recipient_id===friendId)setDirectMessages(old=>old.map(item=>item.id===m.id?{...item,read_at:m.read_at}:item));}).on('broadcast',{event:'typing'},payload=>{const sender=(payload.payload as {user_id?:string}).user_id;if(sender===friendId){setDirectTyping(true);if(directTypingTimerRef.current!==null)window.clearTimeout(directTypingTimerRef.current);directTypingTimerRef.current=window.setTimeout(()=>setDirectTyping(false),1600);}}).subscribe();directChatChannelRef.current=channel;return()=>{if(directTypingTimerRef.current!==null)window.clearTimeout(directTypingTimerRef.current);directChatChannelRef.current=null;setDirectTyping(false);void client.removeChannel(channel);};},[userId,selectedFriend?.profile?.id,loadDirectMessages]);

 const authRedirectUrl=()=>window.location.hostname.endsWith('.pages.dev')?'https://mimox-c5a.pages.dev/':window.location.origin+'/';
 async function authSubmit(e:FormEvent){e.preventDefault();if(!supabase)return;setBusy(true);try{const result=authMode==='signup'?await supabase.auth.signUp({email,password,options:{emailRedirectTo:authRedirectUrl(),data:{username:username.trim()}}}):await supabase.auth.signInWithPassword({email,password});if(result.error)notify(prettyError(result.error));else if(authMode==='signup'&&!result.data.session)notify('الحساب تسجل! حل Gmail واضغط رابط التأكيد، غادي يرجعك للموقع المنشور.');}catch(error){notify(prettyError(error));}finally{setBusy(false);}}
 async function signInWithGoogle(){if(!supabase)return;setBusy(true);try{const {error}=await supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:authRedirectUrl()}});if(error)notify(prettyError(error));}catch(error){notify(prettyError(error));}finally{setBusy(false);}}
 async function resendConfirmation(){if(!supabase||!email.trim()){notify('دخل البريد الإلكتروني ديالك أولاً.');return;}setBusy(true);const {error}=await supabase.auth.resend({type:'signup',email:email.trim(),options:{emailRedirectTo:authRedirectUrl()}});setBusy(false);notify(error?prettyError(error):'عاودنا صيفطنا رابط التأكيد. استعمل آخر رسالة وصلاتك.');}
 async function sendPasswordReset(){if(!supabase||!email.trim()){notify('دخل البريد الإلكتروني ديالك أولاً.');return;}setBusy(true);const {error}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:authRedirectUrl()});setBusy(false);notify(error?prettyError(error):'صيفطنا ليك رابط تغيير كلمة السر. شوف Gmail ديالك.');}
 async function saveNewPassword(e:FormEvent){e.preventDefault();if(!supabase||newPassword.length<8)return;setBusy(true);const {error}=await supabase.auth.updateUser({password:newPassword});setBusy(false);if(error){notify(prettyError(error));return;}setPasswordRecovery(false);setNewPassword('');notify('تبدلات كلمة السر بنجاح.');}
 async function signOut(){stopVoice();await supabase?.auth.signOut();setSession(null);setRoom(null);setTab('home');}
 async function sendFriendRequest(e:FormEvent){e.preventDefault();if(!supabase||!friendSearch.trim())return;setFriendBusy(true);const term=friendSearch.trim();let target:any=null;const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;if(uuid.test(term)){const {data}=await supabase.from('profiles').select('id,username').eq('id',term).maybeSingle();target=data;}else{const {data}=await supabase.from('profiles').select('id,username').ilike('username',term).neq('id',userId).maybeSingle();target=data;}if(!target){setFriendBusy(false);notify('ما لقيناش لاعب بهاد الاسم أو ID.');return;}const {error}=await supabase.rpc('send_friend_request',{p_username:target.username});setFriendBusy(false);if(error)notify(prettyError(error));else{setFriendSearch('');notify('تصيفط طلب الصداقة لـ '+target.username);await loadFriends();}}
 async function acceptFriend(id:string){if(!supabase)return;const {data,error}=await supabase.rpc('accept_friend_request',{p_request_id:id});if(error||!data)notify(error?prettyError(error):'الطلب ما بقاش متاح.');else{notify('زدتي صديق جديد.');await loadFriends();}}
 async function declineFriend(id:string){if(!supabase)return;const {data,error}=await supabase.rpc('decline_friend_request',{p_request_id:id});if(error||!data){notify(error?prettyError(error):'الطلب ما بقاش متاح.');return;}notify('ترفض طلب الصداقة.');await loadFriends();}
 async function removeFriend(id:string){if(!supabase)return;const {error}=await supabase.rpc('remove_friend',{p_friend_id:id});if(error)notify(prettyError(error));else{notify('تحيد الصديق.');await loadFriends();}}
 async function createRoom(){if(!supabase)return;const definition=games.find(g=>g.key===selectedGame);if(!definition){notify('اختار لعبة صحيحة.');return;}const capacities=getRoomCapacityOptions(definition);if(!capacities.includes(maxPlayers)){notify('عدد اللاعبين ما مناسبش لهاد اللعبة.');return;}if(privateRoom&&roomPassword.length<4){notify('كلمة السر خاصها تكون 4 حروف على الأقل.');return;}setBusy(true);const {data,error}=await supabase.rpc('create_room',{p_name:roomName.trim(),p_private:privateRoom,p_max_players:maxPlayers,p_game_key:selectedGame,p_password:privateRoom?roomPassword:null});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(!r){notify('ما قدرناش نصايبو الغرفة.');return;}setRoomDialog(null);setCode(r.room_code);setRoomPassword('');await openRoom({id:r.room_id,code:r.room_code,name:roomName.trim(),is_private:privateRoom,max_players:maxPlayers,status:'open',game_key:selectedGame});}
 async function joinRoom(c:string){if(!supabase)return;setBusy(true);const {data,error}=await supabase.rpc('join_room',{p_code:c.replace(/-/g,'').trim().toUpperCase(),p_password:joinPassword||null});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(r){setRoomDialog(null);setJoinPassword('');await openRoom({id:r.room_id,code:r.room_code,name:r.room_name,is_private:Boolean(r.is_private),max_players:Number(r.max_players)||2,status:'open',game_key:r.game_key||null});}}
 async function shareRoomInvite(){
  if(!room)return;
  const invite='دخل لينا فـ ليلة فالخيمة!\nالغرفة: '+room.name+'\nالكود: '+room.code.match(/.{1,4}/g)?.join('-');
  try{
   if(navigator.share)await navigator.share({title:'دعوة للعب - ليلة فالخيمة',text:invite});
   else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(invite);notify('تنسخات الدعوة، صيفطها لصحابك.');}
  }catch(error){
   if(error instanceof DOMException&&error.name==='AbortError')return;
   notify('ما قدرناش نشاركو الدعوة؛ استعمل الكود: '+room.code);
  }
 }
 async function openRoom(r:Room){
   if(r.game_key!=='haunted_camp'){notify('هاد الغرفة كتستعمل لعبة قديمة ما بقاتش متاحة. صايب غرفة جديدة ديال ليلة فالخيمة.');return;}
   playGameSound('join');setRoom(r);setCode(r.code);if(r.game_key)setSelectedGame(r.game_key);setMaxPlayers(r.max_players);setTab('room');
   const {data:heartbeat,error:heartbeatError}=await supabase!.rpc('heartbeat_room',{p_room_id:r.id});
   if(heartbeatError)notify(prettyError(heartbeatError));
   if(heartbeat===false){
     const {data:activeRoom}=await supabase!.rpc('get_my_active_haunted_room');
     const recovered=Array.isArray(activeRoom)?activeRoom[0]:activeRoom;
     if(!recovered?.room_id){notify('الغرفة ما بقاتش متاحة.');setRoom(null);setTab('rooms');return;}
   }
   await loadRoomData(r.id,r.game_key ?? undefined);
  }
  async function restoreActiveHauntedRoom(){
   if(!supabase||!userId)return;
   const {data,error}=await supabase.rpc('get_my_active_haunted_room');
   if(error){notify(prettyError(error));return;}
   const active=Array.isArray(data)?data[0]:data;
   if(!active?.room_id)return;
   await openRoom({id:active.room_id,code:active.room_code,name:active.room_name,is_private:Boolean(active.is_private),max_players:Number(active.max_players)||10,status:active.status,game_key:active.game_key});
  }
