 function stopVoice(){
  voiceStartingRef.current=false;
  if(voiceChannelRef.current&&supabase){void supabase.removeChannel(voiceChannelRef.current);voiceChannelRef.current=null;}
  peerConnectionsRef.current.forEach(pc=>pc.close());peerConnectionsRef.current.clear();
  remoteAudioRef.current.forEach(audio=>{audio.pause();audio.srcObject=null;});remoteAudioRef.current.clear();
  localStreamRef.current?.getTracks().forEach(track=>track.stop());localStreamRef.current=null;
  pendingIceRef.current.clear();
  voiceSourceRef.current.forEach(source=>{try{source.disconnect();}catch{}});voiceSourceRef.current.clear();voiceAnalyserRef.current.clear();
  if(voiceActivityTimerRef.current!==null){window.clearInterval(voiceActivityTimerRef.current);voiceActivityTimerRef.current=null;}
  if(voiceAudioContextRef.current){void voiceAudioContextRef.current.close().catch(()=>undefined);voiceAudioContextRef.current=null;}
  setVoiceSpeakingIds([]);setVoiceParticipantIds([]);
  manualVoiceMuteRef.current=false;setVoiceActive(false);setVoiceMuted(false);setVoiceStatus('الصوت مطفي');
 }
 function detachVoiceAnalyser(id:string){
   const source=voiceSourceRef.current.get(id);if(source){try{source.disconnect();}catch{}voiceSourceRef.current.delete(id);}
   voiceAnalyserRef.current.delete(id);
  }
  function startVoiceActivityMonitor(){
   if(voiceActivityTimerRef.current!==null)return;
   const tick=()=>{
    const active:string[]=[];
    voiceAnalyserRef.current.forEach((analyser,id)=>{
     const samples=new Uint8Array(analyser.fftSize);analyser.getByteTimeDomainData(samples);
     let energy=0;for(let i=0;i<samples.length;i++){const value=(samples[i]-128)/128;energy+=value*value;}
     if(Math.sqrt(energy/samples.length)>.035)active.push(id);
    });
    setVoiceSpeakingIds(previous=>previous.length===active.length&&previous.every(id=>active.includes(id))?previous:active);
    if(!voiceAnalyserRef.current.size){if(voiceActivityTimerRef.current!==null)window.clearInterval(voiceActivityTimerRef.current);voiceActivityTimerRef.current=null;setVoiceSpeakingIds([]);}
   };
   voiceActivityTimerRef.current=window.setInterval(tick,100);
  }
  function attachVoiceAnalyser(id:string,stream:MediaStream){
   try{
    const Ctor=window.AudioContext||(window as Window & {webkitAudioContext?:typeof AudioContext}).webkitAudioContext;
    if(!Ctor)return;
    const context=voiceAudioContextRef.current||(voiceAudioContextRef.current=new Ctor());
    if(context.state==='suspended')void context.resume().catch(()=>undefined);
    detachVoiceAnalyser(id);
    const source=context.createMediaStreamSource(stream),analyser=context.createAnalyser();
    analyser.fftSize=256;analyser.smoothingTimeConstant=.78;source.connect(analyser);
    voiceSourceRef.current.set(id,source);voiceAnalyserRef.current.set(id,analyser);startVoiceActivityMonitor();
   }catch{/* Voice activity visuals are optional; audio transport continues without them. */}
  }
  async function startVoice(){
  if(!supabase||!room||!userId||voiceActive||voiceStartingRef.current)return;
  if(!navigator.mediaDevices?.getUserMedia){setVoiceStatus('المتصفح ما كيدعمش المايك أو الصفحة ماشي HTTPS.');return;}
  voiceStartingRef.current=true;
  try{
   setVoiceStatus('كنفتح المايك...');
   const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});
   localStreamRef.current=stream;
   stream.getAudioTracks().forEach(track=>track.enabled=!nightMuteRef.current&&!manualVoiceMuteRef.current);
   attachVoiceAnalyser(userId,stream);
   setVoiceStatus('الميك تفتح، كنربط الصوت مع اللاعبين...');
   let iceServers:RTCIceServer[]=[{urls:['stun:stun.cloudflare.com:3478','stun:stun.l.google.com:19302']}];
   try{const iceResponse=await fetch('https://dima-play-turn-api.m40065744.workers.dev/ice',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'}});if(!iceResponse.ok)throw new Error('TURN غير مهيأ');const iceData=await iceResponse.json();if(Array.isArray(iceData.iceServers)&&iceData.iceServers.length)iceServers=iceData.iceServers;}
   catch{setVoiceStatus('TURN مازال ما تهيّأش؛ غادي نجرب الاتصال المباشر.');}
   const channel=supabase.channel('voice:'+room.id,{config:{private:true,presence:{key:userId},broadcast:{ack:true}}});
   voiceChannelRef.current=channel;
   const sendSignal=async(to:string,kind:string,data:any)=>{await channel.send({type:'broadcast',event:'signal',payload:{from:userId,to,kind,data}});};
   const makePeer=(peerId:string,initiator:boolean)=>{
    let pc=peerConnectionsRef.current.get(peerId);if(pc)return pc;
    pc=new RTCPeerConnection({iceServers});
    peerConnectionsRef.current.set(peerId,pc);
    stream.getTracks().forEach(track=>pc!.addTrack(track,stream));
    pc.onicecandidate=e=>{if(e.candidate)void sendSignal(peerId,'ice',e.candidate.toJSON());};
    pc.ontrack=e=>{let audio=remoteAudioRef.current.get(peerId);if(!audio){audio=new Audio();audio.autoplay=true;remoteAudioRef.current.set(peerId,audio);}audio.srcObject=e.streams[0];attachVoiceAnalyser(peerId,e.streams[0]);void audio.play().catch(()=>setVoiceStatus('ضغط على الصفحة باش تسمح بالصوت الوارد.'));};
    pc.onconnectionstatechange=()=>{if(pc&&(pc.connectionState==='failed'||pc.connectionState==='closed')){pc.close();peerConnectionsRef.current.delete(peerId);const audio=remoteAudioRef.current.get(peerId);if(audio){audio.pause();audio.srcObject=null;remoteAudioRef.current.delete(peerId);}detachVoiceAnalyser(peerId);}};
    if(initiator){void (async()=>{const offer=await pc!.createOffer();await pc!.setLocalDescription(offer);await sendSignal(peerId,'offer',pc!.localDescription);})().catch(()=>setVoiceStatus('فشل إنشاء اتصال صوتي مع لاعب.'));}
    return pc;
   };
   channel.on('broadcast',{event:'signal'},async({payload}:any)=>{
    if(!payload||payload.to!==userId||typeof payload.from!=='string'||payload.from===userId)return;
    try{
     let pc=peerConnectionsRef.current.get(payload.from);
     if(payload.kind==='offer'){pc=makePeer(payload.from,false);await pc.setRemoteDescription(payload.data);const queued=pendingIceRef.current.get(payload.from)||[];for(const candidate of queued)await pc.addIceCandidate(candidate);pendingIceRef.current.delete(payload.from);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await sendSignal(payload.from,'answer',pc.localDescription);}
     else if(payload.kind==='answer'&&pc){await pc.setRemoteDescription(payload.data);const queued=pendingIceRef.current.get(payload.from)||[];for(const candidate of queued)await pc.addIceCandidate(candidate);pendingIceRef.current.delete(payload.from);}
     else if(payload.kind==='ice'&&payload.data){if(pc?.remoteDescription)await pc.addIceCandidate(payload.data);else{const q=pendingIceRef.current.get(payload.from)||[];q.push(payload.data);pendingIceRef.current.set(payload.from,q);}}
    }catch{setVoiceStatus('وقع مشكل فالتفاوض الصوتي. عاود دخل للصوت.');}
   });
   channel.on('presence',{event:'sync'},()=>{
    const state=channel.presenceState() as Record<string,any[]>,ids=new Set<string>();
    Object.values(state).flat().forEach(meta=>{if(typeof meta?.user_id==='string'&&meta.user_id!==userId)ids.add(meta.user_id);});
    setVoiceParticipantIds([userId,...[...ids].sort().slice(0,5)]);
     const peers=[...ids].sort().slice(0,5);
    for(const [id,pc] of peerConnectionsRef.current){if(!peers.includes(id)){pc.close();peerConnectionsRef.current.delete(id);const audio=remoteAudioRef.current.get(id);if(audio){audio.pause();audio.srcObject=null;remoteAudioRef.current.delete(id);}detachVoiceAnalyser(id);}}
    if(ids.size>5)setVoiceStatus('الغرفة الصوتية كتقبل 6 مشاركين كحد أقصى فهاد النسخة.');
    else setVoiceStatus('الصوت خدام — '+(ids.size+1)+' مشاركين');
    peers.forEach(id=>{if(userId<id)makePeer(id,true);});
   });
   channel.subscribe(async(status:string)=>{
    if(status==='SUBSCRIBED'){voiceStartingRef.current=false;await channel.track({user_id:userId,joined_at:new Date().toISOString()});setVoiceActive(true);setVoiceStatus('الميك خدام. استعمل زر الكتم إلا بغيتي.');}
    else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'){setVoiceStatus('تعذر الاتصال الصوتي. راجع صلاحيات Realtime.');stopVoice();}
   });
  }catch(e:any){voiceStartingRef.current=false;setVoiceStatus(e?.name==='NotAllowedError'?'خاصك تسمح باستعمال المايك.':e?.message||'تعذر تشغيل المايك.');stopVoice();}
 }
 function toggleVoiceMute(){const next=!voiceMuted;manualVoiceMuteRef.current=next;localStreamRef.current?.getAudioTracks().forEach(track=>track.enabled=!next&&!nightMuteRef.current);setVoiceMuted(next);}
 const forceNightMute=useCallback((muted:boolean)=>{nightMuteRef.current=muted;localStreamRef.current?.getAudioTracks().forEach(track=>track.enabled=!muted&&!manualVoiceMuteRef.current);},[]);
